/* R1354 — stable public Community Membership verification destination */
'use strict';(()=>{const API='https://franklin-navigator-membership.onrender.com',root=document.querySelector('[data-r1354-verification-root]');if(!root)return;const tr=s=>window.FranklinI18n?.translate(s)||s;const node=(t,x,c)=>{const n=document.createElement(t);if(x!==undefined)n.textContent=x;if(c)n.className=c;return n};const id=new URLSearchParams(location.search).get('profile')||'';const valid=/^FR-[A-Z0-9]+-[A-Za-z0-9][A-Za-z0-9._-]{2,100}$/.test(id);function render(r){root.replaceChildren();const card=node('article',undefined,'r1354-recognition-card '+(r.currentMembershipActive?'':'is-historical'));const years=Array.isArray(r.participationYears)?r.participationYears:[],year=r.currentMembershipActive?r.currentQualifyingYear:years[0];card.append(node('div',r.currentMembershipActive?String(year)+' Community Member':years.length?'Past Community Member — '+String(year):'No recorded Community Membership year','r1354-recognition-year'));card.append(node('h2',r.profileName||'Franklin profile'));const status=node('p',r.currentMembershipActive?'Current Community Membership: active':'Current Community Membership: not active','r1354-verify-status '+(r.currentMembershipActive?'is-active':'is-inactive'));card.append(status);if(years.length)card.append(node('p','Participation years: '+years.join(', '),'r1354-recognition-history'));if(r.lastVerifiedAt){try{card.append(node('p','Last verified: '+new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(r.lastVerifiedAt)),'fine-print'))}catch{}}const actions=node('div',undefined,'r1354-recognition-actions');const a=node('a','View Franklin Navigator profile','button primary');a.href='/profiles/'+encodeURIComponent(r.profileId)+'/';actions.append(a);card.append(actions);card.append(node('p',r.explanation||'Community Membership participation recognition is not a government license, professional certification, quality guarantee, ranking or endorsement.','r1354-recognition-disclaimer'));root.append(card)}async function go(){if(!valid){root.textContent=tr('Choose a valid Franklin Navigator profile to verify.');return}try{const res=await fetch(API+'/api/member/public-recognition?profileId='+encodeURIComponent(id),{credentials:'omit',cache:'no-store'}),out=await res.json().catch(()=>({}));if(!res.ok||!out.recognition)throw Error('unavailable');render(out.recognition)}catch{root.textContent=tr('This membership verification is unavailable right now. The profile page remains the safe fallback.')}}go()})();